mapper.select:
SELECT MAX(registrationNo)
FROM bq_registration
WHERE deleted = 0
  AND orderTime >= #{todayStart}
  AND orderTime < #{todayEnd}
  AND registrationNo IS NOT NULL

SELECT r.id, r.orderTime, r.patient, r.gender, r.age, r.ageType, p.idCard, p.mobile, p.address, r.doctor, r.isFirstVisit, r.status FROM bq_registration r LEFT JOIN bq_patient p ON p.name = r.patient AND p.deleted = 0 WHERE r.deleted = 0
AND r.patient LIKE CONCAT('%', #{patientName}, '%')
AND r.doctor = #{doctor}
AND r.orderTime >= #{startTime}
AND r.orderTime <= #{endTime}
ORDER BY r.orderTime DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM bq_registration r
LEFT JOIN bq_patient p ON p.name = r.patient AND p.deleted = 0
WHERE r.deleted = 0

    AND r.patient LIKE CONCAT('%', #{patientName}, '%')


    AND r.doctor = #{doctor}


    AND r.orderTime >= #{startTime}


    AND r.orderTime <= #{endTime}
